'use strict';
// BLACKMAMER dual-VM prepass. Prometheus is installed and pinned at image build
// time; no network access or Lua config supplied by the API at request time.
// The ONLY public output is generated by the outer BLACKMAMER VM.
const fs=require('node:fs/promises');
const fsSync=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const {execFile}=require('node:child_process');
const {promisify}=require('node:util');
const {lowerLuau}=require('./luau-compat-lowering');
const execFileAsync=promisify(execFile);

const PROMETHEUS_REVISION='a98c50165f2a53f6d765a82eee60dfea53803445';
const MAX_BYTES=128*1024;
// Full 11-step VM output has a fixed bootstrap >120 KB even for trivial source.
// Allow realistic functions, while keeping a strict cap for Render Free.
// Full 11-step VM output is much larger than its original Luau input.
 // Keep a bounded larger ceiling, rather than randomly rejecting 1 KB code.
const MAX_FULL_INTERMEDIATE_BYTES=2*1024*1024;
// Leave room for the outer VM and the 120s browser deadline.
// Render Free can need longer than 40s for the complete 11-step profile.
const configuredTimeout=Number(process.env.BLACKMAMER_PROMETHEUS_TIMEOUT_MS);
const TIMEOUT_MS=Number.isInteger(configuredTimeout)&&configuredTimeout>=1000&&configuredTimeout<=90000
  ?configuredTimeout:75000;
const HOME=path.resolve(process.env.BLACKMAMER_PROMETHEUS_HOME||
  path.join(__dirname,'vendor','prometheus'));
const LUA_BINARY=process.env.BLACKMAMER_PROMETHEUS_LUA||'lua5.1';
const PROFILE='Vmify'; // Legacy independently verified default.
const FULL_PROFILE='BlackmamerFull';
const FULL_CONFIG=path.join(__dirname,'prometheus-maximal.lua');
const FULL_STEPS=['SplitStrings','ProxifyLocals','AddVararg',
  'Vmify','EncryptStrings','AntiTamper','ConstantArray',
  'WrapInFunction','Cff','NumbersToExpressions','WatermarkCheck'];
class PrometheusStageError extends Error {
  constructor(code,message,cause){
    super(message);this.name='PrometheusStageError';this.code=code;
    if(cause)this.cause=cause;
  }
}
function available(){
  return fsSync.existsSync(path.join(HOME,'cli.lua'))&&
    fsSync.existsSync(path.join(HOME,'src','prometheus.lua'));
}
function ensureSource(source,target){
  if(typeof source!=='string'||!source.trim())
    throw new PrometheusStageError('DOUBLE_VM_EMPTY','Lua source is empty.');
  if(!['LuaU','Lua51','LuaJIT'].includes(target))
    throw new PrometheusStageError('DOUBLE_VM_TARGET','Unsupported runtime target.');
  if(Buffer.byteLength(source)>MAX_BYTES)
    throw new PrometheusStageError('DOUBLE_VM_INPUT_TOO_LARGE','Original Lua exceeds 128 KB.');
}
async function preprocess(source,target,{timeoutMs=TIMEOUT_MS,profile='Vmify',luaBinary=LUA_BINARY}={}){
  if(!['Vmify','full'].includes(profile))
    throw new PrometheusStageError('PROMETHEUS_PROFILE',
      'Unsupported Prometheus profile');
  const full=profile==='full';
  if(full&&!fsSync.existsSync(FULL_CONFIG))
    throw new PrometheusStageError('PROMETHEUS_FULL_CONFIG_UNAVAILABLE',
      'BLACKMAMER full Prometheus configuration is missing');
  ensureSource(source,target);
  let sourceForPrometheus=source;
  let lowering={applied:false,features:[]};
  if(target==='LuaU'&&full){
    try{
      lowering=lowerLuau(source,'LuaU');
      sourceForPrometheus=lowering.source;
    }catch(error){
      throw new PrometheusStageError('LUAU_SYNTAX_UNSUPPORTED',
        'Luau source cannot be prepared for Prometheus: '+String(error.message).slice(0,150),error);
    }
  }
  if(!available())throw new PrometheusStageError('PROMETHEUS_UNAVAILABLE',
    'Pinned Prometheus compiler not installed on this backend.');
  const temp=await fs.mkdtemp(path.join(os.tmpdir(),'blackmamer-double-vm-'));
  try{
    await fs.chmod(temp,0o700);
    const src=path.join(temp,'source.lua'),output=path.join(temp,'prometheus.lua');
    await fs.writeFile(src,sourceForPrometheus,{mode:0o600,flag:'wx'});
    const args=[path.join(HOME,'cli.lua'),
      ...(full?['--config',FULL_CONFIG]:['--preset',PROFILE]),
      target==='LuaU'?'--LuaU':'--Lua51','--nocolors','--out',output,src];
    const started=Date.now();
    console.info('[BLACKMAMER PROMETHEUS START]',JSON.stringify({
      profile:full?FULL_PROFILE:PROFILE,target,inputBytes:Buffer.byteLength(source),
      normalizedBytes:Buffer.byteLength(sourceForPrometheus),
      luauCompatibility:lowering.features,runner:path.basename(luaBinary),timeoutMs
    }));
    try{
      await execFileAsync(luaBinary,args,{
        cwd:HOME,timeout:timeoutMs,maxBuffer:2*1024*1024,
        windowsHide:true,env:{...process.env,NO_COLOR:'1'}
      });
    }catch(error){
      const timedOut=error.killed||error.signal==='SIGTERM'||
        error.code==='ETIMEDOUT';
      console.warn('[BLACKMAMER PROMETHEUS PROCESS FAILED]',JSON.stringify({
        profile:full?FULL_PROFILE:PROFILE,target,runner:path.basename(luaBinary),
        elapsedMs:Date.now()-started,timeoutMs,reason:timedOut?'timeout':'process-error',
        exitCode:String(error.code||error.signal||'unknown').slice(0,40)
      }));
      if(timedOut)throw new PrometheusStageError('PROMETHEUS_TIMEOUT',
        'Prometheus exceeded the prepass time limit.',error);
      throw new PrometheusStageError('PROMETHEUS_STAGE_FAILED',
        'Prometheus VM prepass failed: '+
          String(error.stderr||error.message||'unknown error').slice(-250),error);
    }
    let stat;
    try{stat=await fs.stat(output);}
    catch(e){throw new PrometheusStageError('PROMETHEUS_EMPTY_OUTPUT',
      'Prometheus did not produce an output file.',e);}
    if(stat.size>(full?MAX_FULL_INTERMEDIATE_BYTES:MAX_BYTES)){
      console.warn('[BLACKMAMER PROMETHEUS CAPACITY]',JSON.stringify({
        profile:full?FULL_PROFILE:PROFILE,target,intermediateBytes:stat.size,
        maxBytes:full?MAX_FULL_INTERMEDIATE_BYTES:MAX_BYTES
      }));
      throw new PrometheusStageError('PROMETHEUS_OUTPUT_TOO_LARGE',
        'Prometheus VM produced '+stat.size+' bytes; Full profile intermediate limit is '+
          Math.round(MAX_FULL_INTERMEDIATE_BYTES/1024)+' KB.');
    }
    if(stat.size===0)throw new PrometheusStageError('PROMETHEUS_EMPTY_OUTPUT',
      'Prometheus generated an empty Lua script.');
    const transformed=await fs.readFile(output,'utf8');
    if(!transformed.trim())throw new PrometheusStageError('PROMETHEUS_EMPTY_OUTPUT',
      'Prometheus generated no Lua code.');
    console.info('[BLACKMAMER PROMETHEUS COMPLETE]',JSON.stringify({
      profile:full?FULL_PROFILE:PROFILE,target,runner:path.basename(luaBinary),
      elapsedMs:Date.now()-started,inputBytes:Buffer.byteLength(source),outputBytes:stat.size
    }));
    return {
      source:transformed,
      meta:{applied:true,vm:true,preset:full?FULL_PROFILE:PROFILE,
        steps:full?FULL_STEPS.slice():['Vmify'],allPrometheusSteps:full,
        revision:PROMETHEUS_REVISION,
        inputBytes:Buffer.byteLength(source),outputBytes:stat.size,
        elapsedMs:Date.now()-started,luauCompatibility:lowering.features,
        sourceNormalized:lowering.applied}
    };
  }finally{await fs.rm(temp,{recursive:true,force:true})}
}
module.exports={preprocess,available,PrometheusStageError,
  PROMETHEUS_REVISION,MAX_BYTES,MAX_FULL_INTERMEDIATE_BYTES,PROFILE,FULL_PROFILE,FULL_STEPS};
